css:
[data-theme="light"] .card:hover,
[data-theme="light"] .top-menu-item:hover,
[data-theme="light"] .action-btn:hover {
  background: var(--surface-2);
}

[data-theme="light"] .service-icon {
  filter: brightness(0);
}

[data-theme="light"] .service-fallback {
  color: #111;
}

[data-theme="light"] .section-header > i,
[data-theme="light"] .top-menu i,
[data-theme="light"] .icon-btn i {
  color: #111;
}

[data-theme="light"] .service-icon {
  filter: none !important;
  opacity: 1;
}

[data-theme="light"] .small-icon-btn:not(.delete-btn) {
  color: var(--text) !important;
}
[data-theme="light"] .small-icon-btn:not(.delete-btn) i {
  color: var(--text) !important;
}

[data-theme="light"] button.delete-btn i {
  color: #ff6b6b !important;
}
[data-theme="light"] button.delete-btn:hover i {
  color: #ff8a8a !important;
}
